private boolean isAdminOrOwner(){String me=my9DigitId;if(me==null||me.isEmpty())me=currentUserId;if(me!=null&&me.equals(roomOwnerId))return true;if(me!=null&&roomAdminList.contains(me))return true;if(currentUserId!=null&&currentUserId.equals(roomOwnerId))return true;if(currentUserId!=null&&roomAdminList.contains(currentUserId))return true;return false;}
private void listenToLockedSeats(){databaseReference.child("rooms").child(roomOwnerId).child("locked_seats").addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){lockedSeats.clear();for(DataSnapshot ds:s.getChildren())if(Boolean.TRUE.equals(ds.getValue(Boolean.class)))lockedSeats.add(ds.getKey());}@Override public void onCancelled(@NonNull DatabaseError e){}});}
