private String flagForCountry(String c){if(c==null)return "🌍";String s=c.toLowerCase();if(s.contains("bangladesh")||s.contains("bd"))return "🇧🇩";if(s.contains("india"))return "🇮🇳";if(s.contains("pakistan"))return "🇵🇰";if(s.contains("saudi"))return "🇸🇦";if(s.contains("oman"))return "🇴🇲";if(s.contains("uae")||s.contains("emirates"))return "🇦🇪";if(s.contains("usa")||s.contains("america"))return "🇺🇸";if(s.contains("uk")||s.contains("england"))return "🇬🇧";return "🌍";}
private String genderIcon(String g){if(g==null)return "👤";String s=g.toLowerCase();if(s.contains("female")||s.contains("girl")||s.contains("woman"))return "♀️";if(s.contains("male")||s.contains("boy")||s.contains("man"))return "♂️";return "👤";}
private Bitmap decodeBase64(String b64){if(b64==null||b64.isEmpty())return null;try{byte[] b=Base64.decode(b64,Base64.DEFAULT);return BitmapFactory.decodeByteArray(b,0,b.length);}catch(Exception e){return null;}}
private void copyRoomId(){ClipboardManager cm=(ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE);if(cm!=null){cm.setPrimaryClip(ClipData.newPlainText("Room ID",roomOwnerId));Toast.makeText(this,"Room ID Copied: "+roomOwnerId+" ✅",Toast.LENGTH_SHORT).show();}}
private void ensureMyIdentity(){if(my9DigitId==null)my9DigitId="";if(my9DigitId.isEmpty())my9DigitId=prefs.getString("USER_9DIGIT_ID","");if(myDisplayName==null||myDisplayName.equals("User"))myDisplayName=prefs.getString("USER_NAME","User");if(myPhotoBase64==null||myPhotoBase64.isEmpty())myPhotoBase64=prefs.getString("USER_PHOTO_BASE64","");if(!my9DigitId.isEmpty()){userDatabaseRef.orderByChild("my9DigitId").equalTo(my9DigitId).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){if(snap.exists()){for(DataSnapshot u:snap.getChildren()){currentUserId=u.getKey();if(u.child("name").getValue()!=null)myDisplayName=String.valueOf(u.child("name").getValue());if(u.child("photoBase64").getValue()!=null)myPhotoBase64=String.valueOf(u.child("photoBase64").getValue());if(u.child("country").getValue()!=null)myCountry=String.valueOf(u.child("country").getValue());if(u.child("gender").getValue()!=null)myGender=String.valueOf(u.child("gender").getValue());prefs.edit().putString("USER_UID",currentUserId).putString("USER_NAME",myDisplayName).putString("USER_PHOTO_BASE64",myPhotoBase64).putString("USER_COUNTRY",myCountry).putString("USER_GENDER",myGender).apply();pushOnlineNow();break;}}else syncByUidFallback();}@Override public void onCancelled(@NonNull DatabaseError e){syncByUidFallback();}});}else syncByUidFallback();}
private void syncByUidFallback(){if(currentUserId==null||currentUserId.isEmpty()){pushOnlineNow();return;}userDatabaseRef.child(currentUserId).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){if(s.exists()){if(s.child("my9DigitId").getValue()!=null)my9DigitId=String.valueOf(s.child("my9DigitId").getValue());if(s.child("name").getValue()!=null)myDisplayName=String.valueOf(s.child("name").getValue());if(s.child("photoBase64").getValue()!=null)myPhotoBase64=String.valueOf(s.child("photoBase64").getValue());if(s.child("country").getValue()!=null)myCountry=String.valueOf(s.child("country").getValue());if(s.child("gender").getValue()!=null)myGender=String.valueOf(s.child("gender").getValue());prefs.edit().putString("USER_9DIGIT_ID",my9DigitId).putString("USER_NAME",myDisplayName).putString("USER_PHOTO_BASE64",myPhotoBase64).apply();}pushOnlineNow();}@Override public void onCancelled(@NonNull DatabaseError e){pushOnlineNow();}});}
private void syncLatestUserProfile(){if(currentUserId.isEmpty()&&my9DigitId.isEmpty())return;String key=!currentUserId.isEmpty()?currentUserId:my9DigitId;userDatabaseRef.child(key).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){if(s.exists()){String n=s.child("name").getValue(String.class);if(n!=null&&!n.isEmpty()){myDisplayName=n;prefs.edit().putString("USER_NAME",n).apply();}String v=s.child("my9DigitId").getValue(String.class);if(v!=null&&!v.isEmpty()){my9DigitId=v;prefs.edit().putString("USER_9DIGIT_ID",v).apply();}String c=s.child("country").getValue(String.class);if(c!=null&&!c.isEmpty())myCountry=c;String l=s.child("language").getValue(String.class);if(l!=null&&!l.isEmpty())myLanguage=l;String g=s.child("gender").getValue(String.class);if(g!=null&&!g.isEmpty())myGender=g;String p=s.child("photoBase64").getValue(String.class);if(p!=null&&!p.isEmpty()){myPhotoBase64=p;prefs.edit().putString("USER_PHOTO_BASE64",p).apply();}pushOnlineNow();}}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void pushOnlineNow(){String key=my9DigitId;if(key==null||key.isEmpty())key=currentUserId;if(key==null||key.isEmpty())key=roomOwnerId;if(key==null||key.isEmpty()||databaseReference==null)return;String n=myDisplayName;if(n==null||n.isEmpty())n=prefs.getString("USER_NAME","User");if(n.equals("User")&&!key.isEmpty())n="User "+key;Map<String,Object> m=new HashMap<>();m.put("name",n);m.put("photoBase64",myPhotoBase64!=null?myPhotoBase64:"");m.put("level","0");m.put("country",myCountry);m.put("gender",myGender);m.put("my9DigitId",key);databaseReference.child("rooms").child(roomOwnerId).child("online_users").child(key).setValue(m);databaseReference.child("rooms").child(roomOwnerId).child("online_users").child(key).onDisconnect().removeValue();}
private void listenToOnlineMembers(){pushOnlineNow();if(databaseReference==null)return;databaseReference.child("rooms").child(roomOwnerId).child("online_users").addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){if(textOnlineCount!=null&&s.exists()&&s.getChildrenCount()>0)textOnlineCount.setText(String.valueOf(s.getChildrenCount()));else if(textOnlineCount!=null&&s.exists())textOnlineCount.setText("1");}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void showChatPopup(){if(bottomBarContainer!=null)bottomBarContainer.setVisibility(View.GONE);if(chatPopupBar!=null)chatPopupBar.setVisibility(View.VISIBLE);if(inputChatMessage!=null){inputChatMessage.requestFocus();InputMethodManager imm=(InputMethodManager)getSystemService(Context.INPUT_METHOD_SERVICE);if(imm!=null)imm.showSoftInput(inputChatMessage,InputMethodManager.SHOW_IMPLICIT);}}
private void hideChatPopup(){if(chatPopupBar!=null)chatPopupBar.setVisibility(View.GONE);if(bottomBarContainer!=null)bottomBarContainer.setVisibility(View.VISIBLE);if(inputChatMessage!=null){inputChatMessage.setText("");InputMethodManager imm=(InputMethodManager)getSystemService(Context.INPUT_METHOD_SERVICE);if(imm!=null)imm.hideSoftInputFromWindow(inputChatMessage.getWindowToken(),0);}}
private void setupChatPopup(){View b=findViewById(R.id.btnOpenChat);if(b!=null)b.setOnClickListener(v->showChatPopup());if(inputChatMessage!=null)inputChatMessage.setOnEditorActionListener((v,a,e)->{sendChatMessage();return true;});if(btnChatOption!=null)btnChatOption.setOnClickListener(v->sendChatMessage());}
