private void sendChatMessage(){if(inputChatMessage==null)return;String msg=inputChatMessage.getText().toString().trim();if(msg.isEmpty()||messagesRef==null)return;String myId=my9DigitId;if(myId==null||myId.isEmpty())myId=currentUserId;if(myId==null||myId.isEmpty())myId=roomOwnerId;final String finalId=myId;final String finalMsg=msg;userDatabaseRef.orderByChild("my9DigitId").equalTo(finalId).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){String realName=myDisplayName;String realPhoto=myPhotoBase64;String realCountry=myCountry;String realGender=myGender;String realLevel="0";if(snap.exists()){for(DataSnapshot u:snap.getChildren()){String n=u.child("name").getValue(String.class);if(n!=null&&!n.isEmpty())realName=n;String p=u.child("photoBase64").getValue(String.class);if(p!=null&&!p.isEmpty())realPhoto=p;String c=u.child("country").getValue(String.class);if(c!=null&&!c.isEmpty())realCountry=c;String g=u.child("gender").getValue(String.class);if(g!=null&&!g.isEmpty())realGender=g;String lv=u.child("level").getValue(String.class);if(lv!=null&&!lv.isEmpty())realLevel=lv;myDisplayName=realName;myPhotoBase64=realPhoto;myCountry=realCountry;myGender=realGender;prefs.edit().putString("USER_NAME",realName).putString("USER_PHOTO_BASE64",realPhoto).putString("USER_COUNTRY",realCountry).apply();break;}}if(realName==null||realName.isEmpty()||realName.equals("User"))realName=prefs.getString("USER_NAME","User");Map<String,Object> m=new HashMap<>();m.put("userId",finalId);m.put("userName",realName);m.put("text",finalMsg);m.put("photoBase64",realPhoto!=null?realPhoto:"");m.put("gender",realGender);m.put("country",realCountry);m.put("level",realLevel);m.put("time",System.currentTimeMillis());messagesRef.push().setValue(m);hideChatPopup();pushOnlineNow();}@Override public void onCancelled(@NonNull DatabaseError e){Map<String,Object> m=new HashMap<>();m.put("userId",finalId);m.put("userName",myDisplayName);m.put("text",finalMsg);m.put("photoBase64",myPhotoBase64!=null?myPhotoBase64:"");m.put("gender",myGender);m.put("country",myCountry);m.put("level","0");m.put("time",System.currentTimeMillis());messagesRef.push().setValue(m);hideChatPopup();pushOnlineNow();}});}
private void listenToChatRealtime(){if(messagesRef==null||chatListContainer==null)return;userDatabaseRef.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot usersSnap){chatRealMap.clear();for(DataSnapshot u:usersSnap.getChildren()){String mid=u.child("my9DigitId").getValue(String.class);if(mid==null||mid.isEmpty())mid=u.getKey();Map<String,String> mm=new HashMap<>();mm.put("name",u.child("name").getValue(String.class)!=null?u.child("name").getValue(String.class):"");mm.put("photo",u.child("photoBase64").getValue(String.class)!=null?u.child("photoBase64").getValue(String.class):"");mm.put("country",u.child("country").getValue(String.class)!=null?u.child("country").getValue(String.class):"");mm.put("level",u.child("level").getValue(String.class)!=null?u.child("level").getValue(String.class):"0");chatRealMap.put(mid,mm);}messagesRef.limitToLast(100).addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){chatListContainer.removeAllViews();if(!s.exists())return;for(DataSnapshot ds:s.getChildren()){String uid=ds.child("userId").getValue(String.class);if(uid==null)uid="";String uname=ds.child("userName").getValue(String.class);if(uname==null)uname="User";String txt=ds.child("text").getValue(String.class);if(txt==null)txt="";String photo=ds.child("photoBase64").getValue(String.class);if(photo==null)photo="";String co=ds.child("country").getValue(String.class);if(co==null)co="";String lv=ds.child("level").getValue(String.class);if(lv==null)lv="0";Map<String,String> real=chatRealMap.get(uid);if(real!=null){if(uname.equals("User")||uname.isEmpty()){if(real.get("name")!=null&&!real.get("name").isEmpty())uname=real.get("name");}if(photo.isEmpty()&&real.get("photo")!=null&&!real.get("photo").isEmpty())photo=real.get("photo");if((co==null||co.isEmpty())&&real.get("country")!=null)co=real.get("country");if((lv==null||lv.equals("0"))&&real.get("level")!=null&&!real.get("level").isEmpty())lv=real.get("level");}LinearLayout row=new LinearLayout(VoiceRoomActivity.this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.TOP);row.setPadding(4,6,4,6);CardView cardAv=new CardView(VoiceRoomActivity.this);LinearLayout.LayoutParams cardLp=new LinearLayout.LayoutParams(72,72);cardLp.setMargins(0,4,8,0);cardAv.setLayoutParams(cardLp);cardAv.setRadius(36);cardAv.setCardElevation(0);Bitmap bmp=decodeBase64(photo);if(bmp!=null){cardAv.setCardBackgroundColor(Color.TRANSPARENT);ImageView av=new ImageView(VoiceRoomActivity.this);av.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));av.setScaleType(ImageView.ScaleType.CENTER_CROP);av.setImageBitmap(bmp);cardAv.addView(av);}else{cardAv.setCardBackgroundColor(Color.parseColor("#FF9800"));TextView letter=new TextView(VoiceRoomActivity.this);letter.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));letter.setGravity(Gravity.CENTER);letter.setTextSize(22);letter.setTextColor(Color.WHITE);letter.setTypeface(null,android.graphics.Typeface.BOLD);letter.setText(uname!=null&&!uname.isEmpty()?uname.substring(0,1).toUpperCase():"U");cardAv.addView(letter);}row.addView(cardAv);LinearLayout box=new LinearLayout(VoiceRoomActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(10,0,0,0);box.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));row.addView(box);TextView tvN=new TextView(VoiceRoomActivity.this);tvN.setText(uname+"  "+flagForCountry(co));tvN.setTextColor(Color.parseColor("#3E2F00"));tvN.setTextSize(12);tvN.setTypeface(null,android.graphics.Typeface.BOLD);box.addView(tvN);TextView tvL=new TextView(VoiceRoomActivity.this);tvL.setText("Lv."+lv);tvL.setTextColor(Color.parseColor("#888888"));tvL.setTextSize(11);box.addView(tvL);TextView tvM=new TextView(VoiceRoomActivity.this);tvM.setText(txt);tvM.setTextColor(Color.parseColor("#222222"));tvM.setTextSize(14);box.addView(tvM);chatListContainer.addView(row);}if(chatScrollView!=null)chatScrollView.post(()->chatScrollView.fullScroll(View.FOCUS_DOWN));}@Override public void onCancelled(@NonNull DatabaseError e){}});}@Override public void onCancelled(@NonNull DatabaseError e){}});}
