private void takeSeat(int idx,String existingSeat){String myId=my9DigitId.isEmpty()?currentUserId:my9DigitId;if(myId==null||myId.isEmpty())myId=roomOwnerId;final String finalMyId=myId;final String finalName=(myDisplayName!=null&&!myDisplayName.isEmpty())?myDisplayName:"User";final String finalPhoto=(myPhotoBase64!=null)?myPhotoBase64:"";if(existingSeat!=null&&!existingSeat.equals("seat_"+idx)){databaseReference.child("rooms").child(roomOwnerId).child("seats").child(existingSeat).removeValue();}DatabaseReference seatRef=databaseReference.child("rooms").child(roomOwnerId).child("seats").child("seat_"+idx);Map<String,Object> m=new HashMap<>();m.put("userId",finalMyId);m.put("userName",finalName);m.put("photoBase64",finalPhoto);seatRef.setValue(m);seatRef.onDisconnect().removeValue();Toast.makeText(VoiceRoomActivity.this,"Seat "+(idx+1)+" e bosechen ✅",Toast.LENGTH_SHORT).show();}
private void removeMySeat(){String myId=my9DigitId.isEmpty()?currentUserId:my9DigitId;if(myId==null||myId.isEmpty())myId=roomOwnerId;final String finalMyId=myId;if(databaseReference==null)return;databaseReference.child("rooms").child(roomOwnerId).child("seats").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){for(DataSnapshot s:snap.getChildren()){String u=s.child("userId").getValue(String.class);if(u!=null&&u.equals(finalMyId)){databaseReference.child("rooms").child(roomOwnerId).child("seats").child(s.getKey()).removeValue();}}}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void listenToFirebaseSeats(){if(databaseReference==null)return;databaseReference.child("rooms").child(roomOwnerId).child("seats").addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){for(int i=0;i<10;i++){View imgView=findViewById(getResources().getIdentifier("seatImg_"+i,"id",getPackageName()));DataSnapshot ss=s.child("seat_"+i);View sl=findViewById(getResources().getIdentifier("seat_"+i,"id",getPackageName()));TextView nameTv=null;if(sl instanceof LinearLayout){LinearLayout ll=(LinearLayout)sl;if(ll.getChildCount()>=2&&ll.getChildAt(1) instanceof TextView)nameTv=(TextView)ll.getChildAt(1);}if(ss.exists()){Bitmap bmp=decodeBase64(ss.child("photoBase64").getValue(String.class));String nm=ss.child("userName").getValue(String.class);if(imgView instanceof TextView){TextView tv=(TextView)imgView;if(bmp!=null){Bitmap roundBmp=getCircularBitmap(bmp);tv.setText("");tv.setBackground(new android.graphics.drawable.BitmapDrawable(getResources(),roundBmp));}else{tv.setText("👤");tv.setBackgroundResource(R.drawable.circle_seat_bg);}}if(nameTv!=null)nameTv.setText(nm!=null?nm:"");}else{if(imgView instanceof TextView){TextView tv=(TextView)imgView;if(lockedSeats.contains("seat_"+i))tv.setText("🔒");else tv.setText("🪑");tv.setBackgroundResource(R.drawable.circle_seat_bg);}if(nameTv!=null){if(i==0)nameTv.setText("Host");else nameTv.setText("");}}}}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private Bitmap getCircularBitmap(Bitmap src){if(src==null)return null;int size=Math.min(src.getWidth(),src.getHeight());int x=(src.getWidth()-size)/2;int y=(src.getHeight()-size)/2;Bitmap squared=Bitmap.createBitmap(src,x,y,size,size);Bitmap output=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(output);android.graphics.Paint paint=new android.graphics.Paint();paint.setAntiAlias(true);canvas.drawARGB(0,0,0,0);canvas.drawCircle(size/2f,size/2f,size/2f,paint);paint.setXfermode(new android.graphics.PorterDuffXfermode(android.graphics.PorterDuff.Mode.SRC_IN));canvas.drawBitmap(squared,0,0,paint);return output;}
